package com.eva.ro.webshop.store;

/**
 * Configurarea UNUI magazin: rândul din {@code EVA_WebStore}, adus în memorie.
 *
 * Aici stă tot ce deosebește un site de altul — firma căreia îi aparține, tenantul de date,
 * domeniile pe care răspunde, tema, limbile, sursa de date. Servletul nu cunoaște niciun
 * client, niciun tenant și niciun domeniu; le ia EXCLUSIV de aici (interdicția §11.4:
 * „fără ID-uri sau AD_Client_ID hardcodate").
 *
 * Imutabil: registrul îl reîncarcă întreg la invalidare, nu-l modifică pe loc — așa un request
 * în curs nu vede niciodată o configurare pe jumătate schimbată.
 */
public final class StoreConfig {

    /** Sursa de date a magazinului (§5.2): fișierele tenantului sau tabelele EVA_WebProduct*. */
    public enum DataSource {
        /** {@code catalog.json} + {@code storefront.json} ale tenantului — implicit. */
        JSON,
        /** {@code EVA_WebProduct}/{@code Lang}/{@code Image} — lucrarea-pereche. */
        DB;

        public static DataSource of(String s) {
            return "DB".equalsIgnoreCase(s == null ? "" : s.trim()) ? DB : JSON;
        }
    }

    private final int clientId;
    private final int orgId;
    private final String tenant;
    private final String domain;
    private final String stagingDomain;
    private final String activeTheme;
    private final java.util.List<String> languages;
    private final String defaultLanguage;
    private final String currency;
    private final DataSource dataSource;
    private final java.math.BigDecimal vatRate;

    public StoreConfig(int clientId, int orgId, String tenant, String domain, String stagingDomain,
            String activeTheme, java.util.List<String> languages, String defaultLanguage,
            String currency, DataSource dataSource) {
        this(clientId, orgId, tenant, domain, stagingDomain, activeTheme, languages,
            defaultLanguage, currency, dataSource, null);
    }

    public StoreConfig(int clientId, int orgId, String tenant, String domain, String stagingDomain,
            String activeTheme, java.util.List<String> languages, String defaultLanguage,
            String currency, DataSource dataSource, java.math.BigDecimal vatRate) {
        this.clientId = clientId;
        this.orgId = orgId;
        this.tenant = tenant;
        this.domain = domain;
        this.stagingDomain = stagingDomain;
        this.activeTheme = activeTheme;
        this.languages = java.util.List.copyOf(languages);
        this.defaultLanguage = defaultLanguage;
        this.currency = currency;
        this.dataSource = dataSource;
        this.vatRate = vatRate;
    }

    public int clientId() {
        return clientId;
    }

    public int orgId() {
        return orgId;
    }

    public String tenant() {
        return tenant;
    }

    public String domain() {
        return domain;
    }

    public String stagingDomain() {
        return stagingDomain;
    }

    public String activeTheme() {
        return activeTheme;
    }

    public java.util.List<String> languages() {
        return languages;
    }

    public String defaultLanguage() {
        return defaultLanguage;
    }

    public String currency() {
        return currency;
    }

    public DataSource dataSource() {
        return dataSource;
    }

    /**
     * Cota de TVA a magazinului, ca fracție (0,19 pentru 19%).
     *
     * <h3>De ce e configurare și nu constantă</h3>
     * Motorul Python are {@code vat_rate = 0.19} scris în cod ({@code cms.py:934}). Din
     * 01.08.2025 cota standard e <b>21%</b> (L141/2025), deci originalul e greșit LEGAL, nu doar
     * învechit. Nu-i imităm ilegalitatea — dar nici nu schimbăm valoarea în timpul măsurătorilor
     * de paritate, fiindcă ar face toate comparațiile de neexplicat. Deci: cota vine din
     * {@code EVA_WebStore.VatRate}, pornește de la 19 și se comută pe 21 la cutover, printr-o
     * editare de configurare.
     *
     * <p>Fixul definitiv — cota din {@code C_Tax} cu valabilitate pe interval — e epica de taxe
     * deschisă la nivel de proiect (importul creează încă 19/9/5); nu se rezolvă de aici.
     */
    public java.math.BigDecimal vatRate(java.time.LocalDate la) {
        return vatRate == null || vatRate.signum() <= 0
            ? cotaLegala(la)   // T159 E: magazinul fără cotă configurată ⇒ TVA_STANDARD din registru la data comenzii
            : vatRate.movePointLeft(2);
    }

    /** T159 E: cota TVA standard (fracție) din registrul legislativ la {@code la}; rândul lipsă = refuz (fără «0.19» scris). */
    public static java.math.BigDecimal cotaLegala(java.time.LocalDate la) {
        return com.eva.ro.webshop.data.RegistruLegal.fractie("TVA_STANDARD", la);
    }

    /**
     * Magazinul e văzut pe o adresă de STAGING?
     *
     * Contează pentru două comportamente pe care planul le cere diferite pe public față de
     * staging: override-ul de temă prin {@code ?theme=} (§6.4) și selectarea tenantului prin
     * {@code ?tenant=} (acceptanța §10.6) — permise DOAR pe staging.
     */
    public boolean isStagingHost(String host) {
        return stagingDomain != null && !stagingDomain.isBlank()
            && stagingDomain.equalsIgnoreCase(host);
    }

    @Override
    public String toString() {
        return "EVA_WebStore[client=" + clientId + " tenant=" + tenant + " domain=" + domain
            + " staging=" + stagingDomain + " theme=" + activeTheme + " sursă=" + dataSource + "]";
    }
}

package com.eva.ro.webshop.data;

import java.math.BigDecimal;
import java.time.LocalDate;

import org.compiere.util.DB;

/**
 * P01.C02.T0003 (P01.T159) lotul E (12_spec.md §3.11, 12a §E) — registrul legislativ NAȚIONAL ({@code EVA_ParametriFiscali},
 * clientul 0), citit de site-ul public fără dependența pluginului contab (MANIFEST: {@code Require-Bundle: org.adempiere.base}):
 * același SQL ca cititorul backend {@code readdb.parametru_legal}, parametrizat, doar citire. Dintre rândurile active care conțin
 * data se ia cel cu {@code ValidFrom} maxim, iar la egalitate rândul {@code Origine = MANUAL} (ca {@code ParametriFiscali.rand},
 * AM-A7-1; T159 D, A-6). Rândul lipsă = {@link ParametruLipsa}, niciodată o valoare implicită scrisă în cod.
 */
public final class RegistruLegal {

    static final String SQL = "SELECT Valoare FROM EVA_ParametriFiscali WHERE AD_Client_ID=0 AND Cheie=? AND IsActive='Y'"
        + " AND ValidFrom<=? AND (ValidTo IS NULL OR ValidTo>=?) ORDER BY ValidFrom DESC,"
        + " CASE WHEN Origine='MANUAL' THEN 0 ELSE 1 END";   // T159 D (A-6, corelația 1): la egalitate, MANUAL

    /** Sursa valorilor (producție = baza iDempiere; testele o înlocuiesc prin {@link #pentruTeste}, fără bază). */
    public interface Sursa {
        /** Valoarea cheii la data dată sau {@code null} dacă nu are rând. */
        BigDecimal valoare(String cheie, LocalDate la);
    }

    private static final Sursa BAZA = (cheie, la) -> {
        java.sql.Timestamp t = java.sql.Timestamp.valueOf(la.atStartOfDay());
        return DB.getSQLValueBD(null, SQL, cheie, t, t);
    };

    private static volatile Sursa sursa = BAZA;

    /** Rândul cheii lipsește la data cerută (refuz, fără valoare implicită). */
    public static final class ParametruLipsa extends IllegalStateException {
        private static final long serialVersionUID = 1L;
        public final String cheie;
        public final LocalDate la;

        ParametruLipsa(String cheie, LocalDate la) {
            super("T159_REGISTRU_LIPSA cheie=" + cheie + " la=" + la);
            this.cheie = cheie;
            this.la = la;
        }
    }

    private RegistruLegal() {
    }

    /** Teste; {@code null} = sursa de producție (baza). */
    public static void pentruTeste(Sursa s) {
        sursa = s == null ? BAZA : s;
    }

    /** Valoarea cheii la data {@code la}; rândul lipsă = {@link ParametruLipsa}. */
    public static BigDecimal valoare(String cheie, LocalDate la) {
        BigDecimal v = sursa.valoare(cheie, la);
        if (v == null)
            throw new ParametruLipsa(cheie, la);
        return v;
    }

    /** Valoarea cheii ca fracție (registrul ține cotele TVA ca procent: 21 ⇒ 0,21; o fracție rămâne). */
    public static BigDecimal fractie(String cheie, LocalDate la) {
        BigDecimal v = valoare(cheie, la);
        return v.compareTo(BigDecimal.ONE) > 0 ? v.movePointLeft(2) : v;
    }
}

