    /**
     * Partea de {@code seo_master} din {@code cms.localize_product()} (`cms.py:567-592`).
     *
     * Face două lucruri distincte, ambele cu urmări vizibile:
     * <ol>
     *   <li><b>curăță recenziile</b> din {@code seo_master} — blocul ajunge, prin
     *       {@code source_payload}, într-un {@code <script>} al paginii; fără curățare, ce a fost
     *       respins la moderare ar fi vizibil oricui deschide sursa;</li>
     *   <li><b>suprapune traducerea limbii curente</b> peste {@code content}/{@code quality}/
     *       {@code merchant}. Iar dacă limba nu e cea implicită și traducere nu există,
     *       {@code content} se RECONSTRUIEȘTE din câmpurile deja localizate — altfel pagina
     *       într-o limbă străină ar afișa descrieri românești sub titluri traduse.</li>
     * </ol>
     */
    private void localizeSeoMaster(Map<String, Object> out, Map<String, Object> p, String lang,
            List<Map<String, Object>> recenzii) {
        Map<String, Object> sm = Localize.map(out.get("seo_master"));
        if (sm.isEmpty()) {
            return;
        }
        sm = Reviews.sanitizeSeoMaster(sm, recenzii);

        Map<String, Object> traduceri = Localize.map(sm.get("translations"));
        Map<String, Object> alLimbii = Localize.map(traduceri.get(lang));
        Map<String, Object> continutTradus = Localize.map(alLimbii.get("content"));
        Map<String, Object> calitateTradusa = Localize.map(alLimbii.get("quality"));
        Map<String, Object> comercialTradus = Localize.map(alLimbii.get("merchant"));

        if (!continutTradus.isEmpty()) {
            Map<String, Object> curent = new LinkedHashMap<>(Localize.map(sm.get("content")));
            curent.putAll(continutTradus);
            sm.put("content", curent);
        } else if (!Localize.DEFAULT_LANG.equals(lang)
                && !Localize.map(sm.get("content")).isEmpty()) {
            String nume = String.valueOf(out.getOrDefault("name", ""));
            String scurta = String.valueOf(out.getOrDefault("short_description", ""));
            String lunga = String.valueOf(out.getOrDefault("description", ""));
            Map<String, Object> refacut = new LinkedHashMap<>();
            refacut.put("h1", nume);
            refacut.put("seo_title", firstText(out.get("seo_title"), nume));
            refacut.put("meta_description", Seo.compact(
                firstText(out.get("seo_description"), lunga, scurta, nume), 160));
            refacut.put("short_description", scurta.isEmpty()
                ? Seo.compact(firstText(lunga, nume), 220) : scurta);
            refacut.put("long_description", firstText(lunga, scurta, nume));
            sm.put("content", refacut);
        }
        if (!calitateTradusa.isEmpty()) {
            Map<String, Object> curent = new LinkedHashMap<>(Localize.map(sm.get("quality")));
            curent.putAll(calitateTradusa);
            sm.put("quality", curent);
        }
        if (!comercialTradus.isEmpty()) {
            Map<String, Object> curent = new LinkedHashMap<>(Localize.map(sm.get("merchant")));
            curent.putAll(comercialTradus);
            sm.put("merchant", curent);
        }
        // Python rescrie seo_master DOAR dacă s-a schimbat ceva sau limba nu e cea implicită;
        // altfel rămâne obiectul deja curățat de recenzii
        boolean schimbat = !continutTradus.isEmpty() || !calitateTradusa.isEmpty()
            || !comercialTradus.isEmpty() || !Localize.DEFAULT_LANG.equals(lang);
        out.put("seo_master", schimbat ? sm : Reviews.sanitizeSeoMaster(
            Localize.map(out.get("seo_master")), recenzii));
    }

    /** Primul argument cu text — echivalentul lui {@code a or b or c} pe șiruri. */
    private static String firstText(Object... valori) {
        for (Object v : valori) {
            String s = v == null ? "" : String.valueOf(v);
            if (!s.isEmpty()) {
                return s;
            }
        }
        return "";
    }

    /** Oglinda lui {@code cms._localize_category()}, inclusiv sortarea copiilor pe nume. */
    private Map<String, Object> localizeCategory(Map<String, Object> c, String lang) {
        Map<String, Object> out = new LinkedHashMap<>(c);
        out.put("name", Localize.text(c.get("name"), lang));
        out.put("description", Localize.text(c.get("description"), lang));
        out.put("slug", Localize.text(c.get("slug"), lang));
        out.put("count", (long) Localize.num(c.get("count")));
        List<Map<String, Object>> kids = new ArrayList<>();
        for (Object k : Localize.list(c.get("children"))) {
            kids.add(localizeCategory(Localize.map(k), lang));
        }
        kids.sort(Comparator.comparing(m -> String.valueOf(m.getOrDefault("name", ""))
            .toLowerCase(Locale.ROOT)));
        out.put("children", kids);
        return out;
    }

