/**
 * Portul părții din {@code app/seo_engine.py} de care are nevoie pagina de produs.
 *
 * <h3>Ce s-a portat și ce NU, cu motivul măsurat</h3>
 * {@code seo_engine.py} are 1.207 linii, din care {@code build_seo_master()} singură are 414.
 * Aceea se apelează în Python DOAR când produsul n-are deja {@code seo_master}. Numărat pe
 * catalogul real: <b>0 din 3.842</b> de produse duc lipsă de {@code seo_master} — e generat la
 * import, nu la randare. Deci nu se portează; în locul ei stă o gardă care strigă în log dacă
 * apare vreodată un produs fără, ca lipsa să se vadă, nu să se manifeste ca pagină săracă.
 *
 * Ce se portează, fiindcă se apelează NECONDIȚIONAT la fiecare pagină de produs:
 * {@link #productKeywords}, {@link #inferProductSemantics}, {@link #productSourcePayload}.
 * Plus {@link #productAdditionalProperties}, care e rezerva pentru {@code additionalProperty}
 * din JSON-LD: azi nu se atinge (toate produsele au {@code specification_table}), dar costă
 * 40 de linii și acoperă cazul în care un tabel de specificații n-are niciun rând valid.
 */
public final class SeoEngine {

    private SeoEngine() {
    }

    /** {@code seo_engine.clean_text()}. */
    public static String cleanText(Object value) {
        // \u00a0 = spatiul neintrerupt; in Python e "\xa0". Scris cu escape, nu literal:
        // e invizibil in editor si s-ar pierde tacut la orice copiere a fisierului.
        String text = (value == null ? "" : String.valueOf(value)).replace('\u00a0', ' ');
        text = Localize.comprimaSpatii(text).trim();
        // „1, 5" între cifre devine „1,5" (zecimala românească spartă de import)
        text = text.replaceAll("(?<=\\d),\\s+(?=\\d)", ",");
        text = text.replaceAll("\\.\\s*\\.", ".");
        return text;
    }

    /** {@code seo_engine.property_value()}: {@code null} dacă numele sau valoarea lipsesc. */
    public static Map<String, Object> propertyValue(String name, Object value, String propertyId) {
        String text = cleanText(value);
        if (name == null || name.isBlank() || text.isEmpty()) {
            return null;
        }
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("@type", "PropertyValue");
        out.put("name", cleanText(name));
        out.put("value", text);
        if (propertyId != null && !propertyId.isBlank()) {
            out.put("propertyID", cleanText(propertyId));
        }
        return out;
    }

    /** {@code seo_engine.product_keywords()}: maximum 80, deduplicat insensibil la caz. */
    public static List<String> productKeywords(Map<String, Object> p, String lang) {
        List<String> values = new ArrayList<>();
        for (String field : new String[]{"name", "sku", "ean", "gtin", "barcode"}) {
            String t = Localize.text(p.get(field), lang);
            if (!t.isEmpty()) {
                values.add(t);
            }
        }
        for (String key : new String[]{"categories", "tags"}) {
            for (Object o : Localize.list(p.get(key))) {
                String t = Localize.text(o, lang);
                if (!t.isEmpty()) {
                    values.add(t);
                }
            }
        }
        for (Object o : Localize.list(p.get("attributes"))) {
            Map<String, Object> a = Localize.map(o);
            values.add(Localize.text(a.get("name"), lang));
            values.add(Localize.text(a.get("value"), lang));
        }
        List<String> out = new ArrayList<>();
        LinkedHashSet<String> vazute = new LinkedHashSet<>();
        for (String v : values) {
            String text = cleanText(v);
            String key = text.toLowerCase(Locale.ROOT);
            if (!text.isEmpty() && vazute.add(key)) {
                out.add(text);
            }
            if (out.size() >= 80) {
                break;
            }
        }
        return out;
    }

